local P=game:GetService("Players") local RunS=game:GetService("RunService") local PFS=game:GetService("PathfindingService") local TS=game:GetService("TweenService") local L=game:GetService("Lighting") local D=game:GetService("Debris") local KILL=true local MSG="LET ME IN" local old=workspace:FindFirstChild("User_F") if old then old:Destroy() end local WHITE=Color3.fromRGB(245,245,245) local GRAY=Color3.fromRGB(163,162,165) local hd=Instance.new("HumanoidDescription") hd.HeadColor=WHITE hd.LeftArmColor=WHITE hd.RightArmColor=WHITE hd.LeftLegColor=WHITE hd.RightLegColor=WHITE hd.TorsoColor=GRAY local rig=P:CreateHumanoidModelFromDescription(hd,Enum.HumanoidRigType.R6) rig.Name="User_F" local hum=rig:FindFirstChildOfClass("Humanoid") local root=rig:WaitForChild("HumanoidRootPart") local head=rig:WaitForChild("Head") for _,v in ipairs(rig:GetDescendants()) do if v.Name=="Animate" or v:IsA("Accessory") or v:IsA("Clothing") or v:IsA("ShirtGraphic") then v:Destroy() elseif v:IsA("BasePart") and v~=root then v.Color=v.Name=="Torso" and GRAY or WHITE end end local bc=rig:FindFirstChildOfClass("BodyColors") if bc then bc.HeadColor3=WHITE bc.LeftArmColor3=WHITE bc.RightArmColor3=WHITE bc.LeftLegColor3=WHITE bc.RightLegColor3=WHITE bc.TorsoColor3=GRAY end if not head:FindFirstChildOfClass("Decal") then local fc=Instance.new("Decal") fc.Name="face" fc.Texture="rbxasset://textures/face.png" fc.Face=Enum.NormalId.Front fc.Parent=head end local glow=Instance.new("PointLight") glow.Color=Color3.new(1,0,0) glow.Brightness=2 glow.Range=10 glow.Parent=head hum.MaxHealth=1000 hum.Health=1000 hum.WalkSpeed=16 hum.BreakJointsOnDeath=false hum.HealthDisplayDistance=0 local animator=hum:FindFirstChildOfClass("Animator") or Instance.new("Animator",hum) local function ang(x,y,z) return CFrame.Angles(math.rad(x),math.rad(y),math.rad(z)) end local function alive(c) local h=c and c:FindFirstChildOfClass("Humanoid") if h and h.Health>0 and c:FindFirstChild("HumanoidRootPart") then return h end en