nter bl.SortOrder=Enum.SortOrder.LayoutOrder bl.Padding=UDim.new(0,8) bl.Parent=bubbles local bn=0 local function bubble(txt) if legacy then pcall(function() game:GetService("Chat"):Chat(head,txt,Enum.ChatColor.White) end) return end bn+=1 for _,c in ipairs(bubbles:GetChildren()) do if c:IsA("Frame") then local tl=c:FindFirstChild("Tail") if tl then tl:Destroy() end if c.LayoutOrder<=bn-3 then c:Destroy() end end end local f=Instance.new("Frame") f.Name="Bubble" f.LayoutOrder=bn f.BackgroundColor3=Color3.new(1,1,1) f.BorderSizePixel=0 f.AutomaticSize=Enum.AutomaticSize.XY f.Size=UDim2.fromOffset(0,0) local cr=Instance.new("UICorner") cr.CornerRadius=UDim.new(0,12) cr.Parent=f local t=Instance.new("TextLabel") t.BackgroundTransparency=1 t.AutomaticSize=Enum.AutomaticSize.XY t.Size=UDim2.fromOffset(0,0) t.Font=Enum.Font.GothamMedium t.TextSize=18 t.TextColor3=Color3.fromRGB(57,59,61) t.Text=txt t.Parent=f local pd=Instance.new("UIPadding") pd.PaddingLeft=UDim.new(0,12) pd.PaddingRight=UDim.new(0,12) pd.PaddingTop=UDim.new(0,8) pd.PaddingBottom=UDim.new(0,8) pd.Parent=t local tl=Instance.new("Frame") tl.Name="Tail" tl.AnchorPoint=Vector2.new(0.5,0.5) tl.Position=UDim2.fromScale(0.5,1) tl.Size=UDim2.fromOffset(12,12) tl.Rotation=45 tl.BackgroundColor3=Color3.new(1,1,1) tl.BorderSizePixel=0 tl.Parent=f f.Parent=bubbles D:AddItem(f,5) end local function say(txt,n,big) for i=1,n or 1 do local b=Instance.new("BillboardGui") b.Size=UDim2.fromOffset(big and 420 or 260,big and 90 or 50) b.StudsOffset=Vector3.new(math.random(-40,40)/10,2.5+math.random(0,40)/10,0) b.AlwaysOnTop=true b.MaxDistance=250 b.LightInfluence=0 local t=Instance.new("TextLabel") t.Size=UDim2.fromScale(1,1) t.BackgroundTransparency=1 t.Text=txt t.TextScaled=true t.Font=Enum.Font.Creepster t.TextColor3=Color3.fromRGB(255,math.random(0,40),math.random(0,40)) t.TextStrokeTransparency=0 t.Rotation=math.random(-15,15) t.Parent=b b.Adornee=head b.Parent=head D:AddItem(b,0.6+math.random()*0.8) end bubble(txt) end local function scream(plr,dur) local pg=plr and plr:FindFirstChildOfClass("PlayerGui") if not pg then return end local g=Instance.new("ScreenGui") g.Name="UF_LETMEIN" g.ResetOnSpawn=false g.IgnoreGuiInset=true g.DisplayOrder=999 local f=Instance.new("Frame") f.Size=UDim2.fromScale(1,1) f.BackgroundColor3=Color3.new(1,0,0) f.BackgroundTransparency=0.85 f.BorderSizePixel=0 f.Parent=g g.Parent=pg D:AddItem(g,dur+0.5) task.spawn(function() local e=os.clock()+dur while os.clock()<e and g.Parent do local t=Instance.new("TextLabel") t.BackgroundTransparency=1 t.Text=MSG t.Font=Enum.Font.Creepster t.TextScaled=true t.TextColor3=Color3.fromRGB(math.random(180,255),0,0) t.TextStrokeTransparency=0.2 t.Size=UDim2.fromScale(math.random(15,45)/100,math.random(6,14)/100) t.Position=UDim2.fromScale(math.random(0,85)/100,math.random(0,90)/100) t.Rotation=math.random(-25,25) t.Parent=g D:AddItem(t,0.4+math.random()*0.6) f.BackgroundTransparency=f.BackgroundTransparency>0.8 and 0.65 or 0.85 task.wait(0.07) end end) end local function screamAll(pos,r,plr,dur) local done={} for _,p in ipairs(near(pos,r)) do done[p]=true scream(p,dur) end if plr and not done[plr] then scream(plr,dur) end end local skyBusy=false local function redSky(dur) if skyBusy then return end skyBusy=true local cc=Instance.new("ColorCorrectionEffect") cc.TintColor=Color3.fromRGB(255,40,40) cc.Saturation=0.4 cc.Contrast=0.3 cc.Parent=L local oA,oO,oF=L.Ambient,L.OutdoorAmbient,L.FogColor L.Ambient=Color3.fromRGB(120,0,0) L.OutdoorAmbient=Color3.fromRGB(160,0,0) L.FogColor=Color3.fromRGB(120,0,0) local atm=L:FindFirstChildOfClass("Atmosphere") local made=atm==nil local oc,od,oh,ods if made then atm=Instance.new("Atmosphere") atm.Density=0.35 atm.Parent=L else oc,od,oh,ods=atm.Color,atm.Decay,atm.Haze,atm.Density end atm.Color=Color3.fromRGB(255,0,0) atm.Decay=Color3.fromRGB(120,0,0) atm.Haze=2.5 task.delay(dur,function() L.Ambient,L.OutdoorAmbient,L.FogColor=oA,oO,oF if made then atm:Destroy() else atm.Color,atm.Decay,atm.Haze,atm.Density=oc,od,oh,ods end local tw=TS:Create(cc,TweenInfo.new(0.4),{TintColor=Color3.new(1,1,1),Saturation=0,Contrast=0}) tw:Play() tw.Completed:Wait() cc:Destroy() skyBusy=false end) end local function flicker(pos,r) local ls={} for _,v in ipairs(workspace:GetDescendants()) do if v:IsA("Light") and v.Parent~=head then local pp=v.Parent local p=pp:IsA("BasePart") and pp.Position or pp:IsA("Attachment") and pp.WorldPosition if p and (p-pos).Magnitude<r then table.insert(ls,{v,v.Enabled}) end end end task.spawn(function() for i=1,10 do for _,x in ipairs(ls) do if x[1].Parent then x[1].Enabled=not x[1].Enabled end end task.wait(math.random(3,12)/100) end for _,x in ipairs(ls) do if x[1].Parent then x[1].Enabled=x[2] end end end) end local function shatter(x,dir) local cf,s=x.CFrame,x.Size local th=math.clamp(math.min(s.X,s.Y,s.Z),0.05,0.4) for i=1,math.clamp(math.floor(s.X*s.Y/2),8,30) do local sh=Instance.new("Part") sh.Name="UF_Shard" sh.Size=Vector3.new(math.random(2,12)/10,math.random(2,12)/10,th) sh.CFrame=cf*CFrame.new((math.random()-0.5)*s.X,(math.random()-0.5)*s.Y,(math.random()-0.5)*s.Z)*CFrame.Angles(math.random()*6,math.random()*6,math.random()*6) sh.Material=x.Material sh.Color=x.Color sh.Transparency=x.Transparency sh.Reflectance=x.Reflectance sh.Parent=workspace sh.AssemblyLinearVelocity=dir*math.random(25,55)+Vector3.new(math.random(-15,15),math.random(5,20),math.random(-15,15)) sh.AssemblyAngularVelocity=Vector3.new(math.random(-20,20),math.random(-20,20),math.random(-20,20)) D:AddItem(sh,8) end x:Destroy() end local function loosen(x,pos,dir) for _,j in ipairs(x:GetJoints()) do j:Destroy() end x.Anchored=false x.AssemblyLinearVelocity=(x.Position-pos+Vector3.new(0,0.01,0)).Unit*math.random(10,35)+dir*20+Vector3.new(0,math.random(5,25),0) x.AssemblyAngularVelocity=Vector3.new(math.random(-6,6),math.random(-6,6),math.random(-6,6)) end local function collapse(pos,r,dir) local op=OverlapParams.new() op.FilterType=Enum.RaycastFilterType.Exclude op.FilterDescendantsInstances=params().FilterDescendantsInstances local n=0 local floorY=root.Position.Y-2.2 for _,x in ipairs(workspace:GetPartBoundsInRadius(pos,r,op)) do if n>=80 then break end if x.Name~="UF_Shard" and breakable(x) and x.Position.Y+x.Size.Y/2>floorY then n+=1 if isWin(x) then shatter(x,dir) else loosen(x,pos,dir) end end end end local function obstacle(tp) local rp=params() local best,bd=nil,1e9 for _,h in ipairs({-1,0.8,2}) do local o=root.Position+Vector3.new(0,h,0) local d=Vector3.new(tp.X,o.Y,tp.Z)-o if d.Magnitude>0.1 then local r=workspace:Raycast(o,d.Unit*math.min(d.Magnitude,40),rp) if r and breakable(r.Instance) and (r.Position-o).Magnitude<bd then best,bd=r,(r.Position-o).Magnitude end end end return best end local J={} for _,n in ipairs({"Neck","RootJoint","Right Shoulder","Left Shoulder"}) do local m=rig:FindFirstChild(n,true) if m and m:IsA("Motor6D") then J[n]={m=m,c0=m.C0,cur=CFrame.identity,last=CFrame.identity} end end local mode="idle" local twitch,twT=CFrame.identity,0 local function arms(fr,fl,out) return {["Right Shoulder"]=ang(-(out or 0),0,fr),["Left Shoulder"]=ang(-(out or 0),0,-fl)} end local function pose(t) local p={} if mode=="bang" then local s1,s2=math.abs(math.sin(t*12)),math.abs(math.sin(t*12+1.6)) p=arms(95+s1*45,95+s2*45) p.RootJoint=ang(8+s1*5,0,0) p.Neck=ang(10+math.random(-6,6),0,math.random(-8,8)) elseif mode=="scream" then local j=math.random(-10,10) p=arms(20,20,75+j) p.Neck=ang(-40+j,0,j) p.RootJoint=ang(-8,0,0) elseif mode=="reach" then local w=math.sin(t*6)*12 p=arms(85+w,85-w) p.RootJoint=ang(8,0,0) p.Neck=ang(8,0,math.sin(t*3)*15) elseif mode=="chase" then p.Neck=ang(10,0,0) p.RootJoint=ang(6,0,0) end if twT>t then p.Neck=(p.Neck or CFrame.identity)*twitch end return p end local spawnCF=CFrame.new(0,10,0) local sl=workspace:FindFirstChildWhichIsA("SpawnLocation",true) if sl then spawnCF=sl.CFrame+Vector3.new(0,4,0) end local ps=P:GetPlayers() local sc=#ps>0 and ps[math.random(#ps)].Character if alive(sc) then local tr=sc.HumanoidRootPart local back=-tr.CFrame.LookVector local r=workspace:Raycast(tr.Position,back*35,params()) local pos=r and r.Position-back*2 or tr.Position+back*35 local g=workspace:Raycast(pos+Vector3.new(0,3,0),Vector3.new(0,-60,0),params()) if g then pos=g.Position+Vector3.new(0,3.2,0) end spawnCF=CFrame.lookAt(pos,Vector3.new(tr.Position.X,pos.Y,tr.Position.Z)) end rig:PivotTo(spawnCF) rig.Parent=workspace pcall(function() root:SetNetworkOwner(nil) end) local T={} for k,id in pairs({idle=180435571,walk=180426354,run=180426354}) do local a=Instance.new("Animation") a.AnimationId="rbxassetid://"..id local ok,tr=pcall(function() return animator:LoadAnimation(a) end) if ok and tr then T[k]=tr end end local curAnim local function play(n,v) local tr=T[n] if not tr then return end if curAnim~=n then for k,o in pairs(T) do if k~=n and o.IsPlaying then o:Stop(0.25) end end tr:Play(0.25) curAnim=n end if n~="idle" then tr:AdjustSpeed(math.clamp(v/16,0.6,2)) end end local t0=os.clock() local hb hb=RunS.Heartbeat:Connect(function(dt) if not rig.Parent then hb:Disconnect() return end local t=os.clock()-t0 if math.random()<dt*0.4 then twitch=ang(math.random(-35,35),math.random(-50,50),math.random(-30,30)) twT=t+0.12 end local p=pose(t) local a=1-math.exp(-dt*14) for n,j in pairs(J) do if j.m.Parent then j.cur=j.cur:Lerp(p[n] or CFrame.identity,a) local _,d=(j.cur:Inverse()*j.last):ToAxisAngle() if d>0.003 then j.m.C0=j.c0*j.cur j.last=j.cur end end end local v=(root.AssemblyLinearVelocity*Vector3.new(1,0,1)).Magnitude if hum.Health<=0 then return end play((mode=="bang" or mode=="scream") and "idle" or (v>1 and (hum.WalkSpeed>=20 and "run" or "walk") or "idle"),v) end) local function vis(on) for _,x in ipairs(rig:GetDescendants()) do if x:IsA("BasePart") and x~=root or x:IsA("Decal") then x.Transparency=on and 0 or 1 end end end local function blink(cf) for i=1,3 do vis(false) task.wait(0.05) vis(true) task.wait(0.05) end vis(false) say(MSG,3) rig:PivotTo