on,80) local e=os.clock()+2.5 while os.clock()<e and rig.Parent do say(MSG,math.random(2,5),math.random()<0.4) task.wait(0.12) end if math.random()<0.5 then redSky(1) end end local function jumpscare(plr) local pg=plr:FindFirstChildOfClass("PlayerGui") if not pg then return end local g=Instance.new("ScreenGui") g.Name="UF_Scare" g.IgnoreGuiInset=true g.ResetOnSpawn=false g.DisplayOrder=1000 local f=Instance.new("Frame") f.Size=UDim2.fromScale(1,1) f.BackgroundColor3=Color3.new(0,0,0) f.BorderSizePixel=0 f.Parent=g local t=Instance.new("TextLabel") t.AnchorPoint=Vector2.new(0.5,0.5) t.Position=UDim2.fromScale(0.5,0.5) t.Size=UDim2.fromScale(0.3,0.15) t.BackgroundTransparency=1 t.Text=MSG t.TextScaled=true t.Font=Enum.Font.Creepster t.TextColor3=Color3.new(1,0,0) t.TextStrokeTransparency=0 t.Parent=f g.Parent=pg TS:Create(t,TweenInfo.new(0.35,Enum.EasingStyle.Back),{Size=UDim2.fromScale(1.1,0.6)}):Play() task.spawn(function() for i=1,12 do f.BackgroundColor3=i%2==0 and Color3.new(0,0,0) or Color3.fromRGB(90,0,0) t.Rotation=math.random(-8,8) task.wait(0.08) end end) D:AddItem(g,1.8) end task.spawn(function() local cd={} while rig.Parent and hum.Health>0 do for _,p in ipairs(P:GetPlayers()) do local h=alive(p.Character) if h and (p.Character.HumanoidRootPart.Position-root.Position).Magnitude<4 and (cd[p] or 0)<os.clock() then cd[p]=os.clock()+6 jumpscare(p) snd("rbxasset://sounds/collide.wav",root,5,0.4) if KILL then h.Health=0 end task.spawn(function() mode="scream" say("I'M IN",6,true) task.wait(1) mode="chase" end) end end task.wait(0.1) end end) hum.Died:Connect(function() mode="scream" say(MSG,10,true) redSky(1) task.delay(4,function() rig:Destroy() end) end) redSky(1) flicker(root.Position,150) say(MSG,6,true) for _,p in ipairs(P:GetPlayers()) do scream(p,1.2) end task.spawn(function() while rig.Parent and hum.Health>0 do local plr,dist=nearest() if not plr then mode="idle" if math.random()<0.2 then say("let me in...",1) end task.wait(1) else local tr=plr.Character.HumanoidRootPart local hit=obstacle(tr.Position) if hit and isWin(hit.Instance) and (hit.Position-root.Position).Magnitude<5.5 then breach(hit.Instance,hit.Position,plr) else local path=PFS:CreatePath({AgentRadius=2.2,AgentHeight=5.5,AgentCanJump=true,WaypointSpacing=4}) local ok=pcall(function() path:ComputeAsync(root.Position,tr.Position) end) local wps=ok and path.Status==Enum.PathStatus.Success and path:GetWaypoints() or nil local len=0 if wps then for i=2,#wps do len+=(wps[i].Position-wps[i-1].Position).Magnitude end end if wps and not (hit and len>dist*2.5) then begs=0 mode=dist<25 and "reach" or "chase" hum.WalkSpeed=math.min(16+rage*2+(dist<40 and 6 or 0),30) for i=2,math.min(#wps,7) do if wps[i].Action==Enum.PathWaypointAction.Jump then hum.Jump=true end if not moveTo(wps[i].Position,1.2) then break end local h2=obstacle(tr.Position) if h2 and isWin(h2.Instance) and (h2.Position-root.Position).Magnitude<5.5 then break end end if dist>30 and math.random()<0.05 then local d=Vector3.new(tr.Position.X-root.Position.X,0,tr.Position.Z-root.Position.Z).Unit if not workspace:Raycast(root.Position,d*14,params()) then local p=root.Position+d*12 blink(CFrame.lookAt(p,Vector3.new(tr.Position.X,p.Y,tr.Position.Z))) end end else mode="reach" hum.WalkSpeed=math.min(18+rage*2,30) if hit then if (hit.Position-root.Position).Magnitude>5.5 then moveTo(hit.Position-(hit.Position-root.Position).Unit*3,2) end if hit.Instance.Parent and (hit.Position-root.Position).Magnitude<12 then breach(hit.Instance,hit.Position,plr) end else moveTo(tr.Position,1.5) begs+=1 if begs%3==0 then beg(plr) end if begs>=9 and alive(plr.Character) then begs=0 blink(behind(plr.Character.HumanoidRootPart,6)) end end end end end task.wait() end end)
